func newObservationHostController(t *testing.T, ctx context.Context, js jetstream.JetStream, control *authority.Runtime, artifacts host.ArtifactStore) *host.Controller {
	t.Helper()
	_, responseKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	controller, err := host.NewController(ctx, host.ControllerConfig{Cell: "gru", Conn: js.Conn(), JS: js, Artifacts: artifacts,
		ResponseKey: responseKey, StateReplicas: 1, HostMutations: control,
		AuthorityEpoch: func() uint64 { return control.Current().Epoch }, AuthorityGuard: control.Guard})
	if err != nil {
		t.Fatal(err)
	}
	return controller
}

func registerObservationHost(t *testing.T, ctx context.Context, controller *host.Controller, node, environment string) host.Registration {
	t.Helper()
	public, _, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	user, err := nkeys.CreateUser()
	if err != nil {
		t.Fatal(err)
	}
	defer user.Wipe()
	userID, err := user.PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	registration := host.Registration{ID: entityid.Derive("host", "gru", node), Cell: "gru", Node: node, Environment: environment,
		Roles: []string{swarmruntime.FunctionWorkerRole}, Generation: 1, PublicKey: base64.StdEncoding.EncodeToString(public), NATSUserPublicKey: userID}
	if _, err := controller.Register(ctx, registration); err != nil {
		t.Fatal(err)
	}
	return registration
}

func (controller functionController) observeFunctions(ctx context.Context, hosts func(context.Context) ([]host.HostStatus, error), membership func(context.Context, string) (swarmruntime.VerifiedWorkerMembership, error)) ([]globalview.FunctionObservation, error) {
	if controller.config.Authority == nil || controller.config.Client == nil || controller.config.Material.Issuer == nil || hosts == nil || membership == nil {
		return nil, errors.New("authenticated function observation sources unavailable")
	}
	entries, err := controller.config.Authority.ListFunctionIntents(ctx)
	if err != nil {
		return nil, err
	}
	if len(entries) > 32 {
		return nil, errors.New("function observation inventory exceeds 32 admitted functions")
	}
	registered, err := hosts(ctx)
	if err != nil {
		return nil, err
	}
	services, err := controller.config.Client.ListServices(ctx, &api.ListServicesRequest{})
	if err != nil {
		return nil, err
	}
	var observations []globalview.FunctionObservation
	for _, entry := range entries {
		intent, err := authority.DecodeFunctionIntent(entry)
		if err != nil {
			return nil, err
		}
		claim := intent.Claim
		if claim.Cell != strings.ToUpper(controller.config.Cell) || claim.Environment != controller.config.Environment {
			return nil, release.ErrExpectationMismatch
		}
		observation := globalview.FunctionObservation{TenantID: claim.TenantID, FunctionID: claim.FunctionID, Revision: claim.Revision, Digest: claim.Digest, State: "unavailable"}
		proof, err := controller.config.Material.Reader.CurrentFunction(ctx, claim.TenantID, claim.FunctionID)
		if err != nil || proof.EnvelopeSHA256() != intent.EnvelopeSHA256 {
			observations = append(observations, observation)
			continue
		}
		var selected []*api.Service
		for _, service := range services.Services {
			labels := service.Spec.Annotations.Labels
			if labels[swarmruntime.LabelRole] == swarmruntime.FunctionWorkerRole && labels[swarmruntime.LabelFunctionTenant] == claim.TenantID && labels[swarmruntime.LabelFunctionID] == claim.FunctionID && labels[swarmruntime.LabelRegion] == catalog.OCIRegion(claim.Cell) && labels[swarmruntime.LabelEnvironment] == claim.Environment {
				selected = append(selected, service)
			}
		}
		if len(selected) == 0 {
			observation.State, observation.ObservedAt = "unplaced", time.Now().UTC()
			observations = append(observations, observation)
			continue
		}
		if len(selected) != 1 {
			return nil, errors.New("function observation has ambiguous managed services")
		}
		tasks, err := controller.config.Client.ListTasks(ctx, &api.ListTasksRequest{Filters: &api.ListTasksRequest_Filters{ServiceIDs: []string{selected[0].ID}, DesiredStates: []api.TaskState{api.TaskStateRunning}}})
		if err != nil {
			return nil, err
		}
		if len(tasks.Tasks) == 0 {
			observation.State, observation.ObservedAt = "unplaced", time.Now().UTC()
			observations = append(observations, observation)
			continue
		}
		if len(tasks.Tasks) > 2 {
			return nil, errors.New("function observation exceeds bounded current task inventory")
		}
		for _, task := range tasks.Tasks {
			current := observation
			current.TaskID, current.NodeID = task.ID, task.NodeID
			if task.NodeID == "" {
				current.State, current.ObservedAt = "unplaced", time.Now().UTC()
			} else if task.Status.State == api.TaskStateRunning {
				snapshot, err := controller.observeFunctionTask(ctx, proof, task, registered, hosts, membership)
				if err == nil {
					current.State, current.Snapshot, current.ObservedAt = "observed", &snapshot, snapshot.ObservedAt
				}
			}
			observations = append(observations, current)
		}
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	return observations, nil
}

func (controller functionController) observeFunctionTask(ctx context.Context, proof release.VerifiedFunction, task *api.Task, registered []host.HostStatus, hosts func(context.Context) ([]host.HostStatus, error), membership func(context.Context, string) (swarmruntime.VerifiedWorkerMembership, error)) (functions.Snapshot, error) {
	node, err := controller.config.Client.GetNode(ctx, &api.GetNodeRequest{NodeID: task.NodeID})
	if err != nil || node == nil || node.Node == nil {
		return functions.Snapshot{}, errors.New("function task host observation unavailable")
	}
	index := slices.IndexFunc(registered, func(status host.HostStatus) bool {
		return status.Registration.ID == node.Node.Spec.Annotations.Name && status.Verified && !status.Retired
	})
	if index < 0 {
		return functions.Snapshot{}, errors.New("function task host is not currently admitted")
	}
	registration := registered[index].Registration
	member, err := membership(ctx, task.NodeID)
	if err != nil || member.Validate() != nil || member.NodeID() != task.NodeID || member.RegistrationID() != registration.ID ||
		member.OCIRegion() != catalog.OCIRegion(proof.Claim().Cell) || !strings.EqualFold(member.Cell(), proof.Claim().Cell) || member.Role() != "wasm" ||
		member.InstanceID() != node.Node.Spec.Annotations.Labels[swarmruntime.LabelInstanceID] ||
		member.Info().Generation != registration.Generation || member.Info().PublicKey != registration.PublicKey || member.Info().NATSUserPublicKey != registration.NATSUserPublicKey {
		return functions.Snapshot{}, errors.New("function task lacks current independent worker membership")
	}
	fingerprint, err := swarmruntime.ContainerTaskFingerprint(task)
	if err != nil {
		return functions.Snapshot{}, err
	}
	binding := functionmaterial.Binding{TaskID: task.ID, ServiceID: task.ServiceID, NodeID: task.NodeID, InstanceID: member.InstanceID(), Region: member.OCIRegion(), HostID: registration.ID, Fingerprint: fingerprint}
	before, err := controller.recipient(ctx, registration, binding)
	if err != nil || before.EnvelopeSHA256() != proof.EnvelopeSHA256() {
		return functions.Snapshot{}, errors.New("function snapshot recipient is no longer current")
	}
	ip, err := netip.ParseAddr(member.PrivateIP())
	if err != nil || !ip.Is4() || !ip.IsPrivate() {
		return functions.Snapshot{}, errors.New("function task OCI primary address is unavailable")
	}
	cert, key, ca, err := controller.config.Material.Issuer.IssueFunctionClientTLS(proof)
	if err != nil {
		return functions.Snapshot{}, err
	}
	defer clear(key)
	identity, err := tls.X509KeyPair(cert, key)
	if err != nil {
		return functions.Snapshot{}, errors.New("function snapshot client identity unavailable")
	}
	snapshot, err := functions.ReadSnapshot(ctx, proof, netip.AddrPortFrom(ip, 8080), identity, ca)
	if err != nil {
		return functions.Snapshot{}, err
	}
	if snapshot.Architecture != member.Architecture() {
		return functions.Snapshot{}, errors.New("function snapshot differs from admitted worker architecture")
	}
	after, err := controller.recipient(ctx, registration, binding)
	if err != nil || after.EnvelopeSHA256() != proof.EnvelopeSHA256() {
		return functions.Snapshot{}, errors.New("function snapshot recipient changed while collecting")
	}
	confirmed, err := membership(ctx, task.NodeID)
	if err != nil || confirmed.Validate() != nil || member.Validate() != nil {
		return functions.Snapshot{}, errors.New("function snapshot worker membership unavailable after collection")
	}
	beforeInfo, afterInfo := member.Info(), confirmed.Info()
	beforeInfo.ObservedAt, beforeInfo.ExpiresAt, afterInfo.ObservedAt, afterInfo.ExpiresAt = time.Time{}, time.Time{}, time.Time{}, time.Time{}
	if beforeInfo != afterInfo {
		return functions.Snapshot{}, errors.New("function snapshot worker membership changed while collecting")
	}
	latest, err := hosts(ctx)
	if err != nil || !slices.ContainsFunc(latest, func(status host.HostStatus) bool {
		current := status.Registration
		return status.Verified && !status.Retired && current.ID == registration.ID && current.Generation == registration.Generation && current.PublicKey == registration.PublicKey && current.NATSUserPublicKey == registration.NATSUserPublicKey
	}) {
		return functions.Snapshot{}, errors.New("function snapshot host admission changed while collecting")
	}
	return snapshot, nil
}

func (reader Reader) currentFunction(ctx context.Context, tenant, function string) (release.VerifiedFunction, uint64, error) {
	if reader.Authority == nil || reader.Artifacts == nil || reader.Roots == nil {
		return release.VerifiedFunction{}, 0, ErrMaterial
	}
	entry, err := reader.Authority.ReadFunctionIntent(ctx, tenant, function)
	if err != nil {
		return release.VerifiedFunction{}, 0, err
	}
	intent, err := authority.DecodeFunctionIntent(entry)
	if err != nil {
		return release.VerifiedFunction{}, 0, err
	}
	claim := intent.Claim
	info, err := reader.Artifacts.GetInfo(ctx, "sha256-"+claim.Digest)
	if err != nil {
		return release.VerifiedFunction{}, 0, err
	}
	if info.Size != uint64(claim.Bytes) || info.Size == 0 || info.Size > release.MaxFunctionModuleBytes || info.Opts != nil && info.Opts.Link != nil {
		return release.VerifiedFunction{}, 0, ErrMaterial
	}
	object, err := reader.Artifacts.Get(ctx, "sha256-"+claim.Digest)
	if err != nil {
		return release.VerifiedFunction{}, 0, err
	}
	module, readErr := io.ReadAll(io.LimitReader(object, release.MaxFunctionModuleBytes+1))
	closeErr := object.Close()
	if readErr != nil || closeErr != nil || len(module) > release.MaxFunctionModuleBytes {
		return release.VerifiedFunction{}, 0, ErrMaterial
	}
	proof, err := release.VerifyFunctionCurrent(intent.Envelope, intent.Delegation, module, reader.Roots(), release.FunctionExpectation{
		Environment: claim.Environment, Cell: claim.Cell, TenantID: claim.TenantID, FunctionID: claim.FunctionID,
		Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: claim.Sequence,
	}, time.Now())
	if err != nil || proof.EnvelopeSHA256() != intent.EnvelopeSHA256 {
		return release.VerifiedFunction{}, 0, ErrMaterial
	}
	return proof, entry.Sequence, nil
}

// CurrentFunction resolves the durable desired release without granting a task.
func (reader Reader) CurrentFunction(ctx context.Context, tenant, function string) (release.VerifiedFunction, error) {
	proof, _, err := reader.currentFunction(ctx, tenant, function)
	return proof, err
}

func (r *Runtime) CommitFunctionIntent(ctx context.Context, epoch uint64, operationID string,
	expectedSequence uint64, proof release.VerifiedFunction,
) (uint64, error) {
	if !proof.Valid() {
		return 0, trust.ErrExpired
	}
	intent := FunctionIntent{Claim: proof.Claim(), EnvelopeSHA256: proof.EnvelopeSHA256(),
		Envelope: proof.Envelope(), Delegation: proof.Delegation()}
	key, err := functionIntentKey(intent.Claim.TenantID, intent.Claim.FunctionID)
	if err != nil {
		return 0, err
	}
	if r == nil || strings.ToLower(intent.Claim.Cell) != r.config.Scope {
		return 0, release.ErrExpectationMismatch
	}
	payload, err := json.Marshal(intent, json.FormatNilSliceAsNull(true))
	if err != nil {
		return 0, err
	}
	return r.commitMutationVerified(ctx, epoch, MutationFunctionIntent, key, operationID,
		expectedSequence, payload, func(ctx context.Context) error {
			if !proof.Valid() {
				return trust.ErrExpired
			}
			prior, err := r.ReadFunctionIntent(ctx, intent.Claim.TenantID, intent.Claim.FunctionID)
			if !proof.Valid() {
				return trust.ErrExpired
			}
			if errors.Is(err, ErrNotFound) {
				return nil
			}
			if err != nil {
				return err
			}
			current, err := DecodeFunctionIntent(prior)
			if err != nil {
				return err
			}
			if intent.Claim.Sequence < current.Claim.Sequence ||
				intent.Claim.Sequence == current.Claim.Sequence && !bytes.Equal(payload, prior.Payload) {
				return ErrConflict
			}
			return nil
		})
}

func (r *Runtime) ReadFunctionIntent(ctx context.Context, tenantID, functionID string) (LogEntry, error) {
	key, err := functionIntentKey(tenantID, functionID)
	if err != nil {
		return LogEntry{}, err
	}
	return r.ReadHostMutation(ctx, MutationFunctionIntent, key)
}

func (r *Runtime) ListFunctionIntents(ctx context.Context) ([]LogEntry, error) {
	if r == nil {
		return nil, ErrNotFound
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return listFunctionIntents(ctx, r.readStream, r.config.Scope)
}

func (r *Reader) ListFunctionIntents(ctx context.Context) ([]LogEntry, error) {
	if r == nil || r.stream == nil {
		return nil, ErrNotFound
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	return listFunctionIntents(ctx, r.stream, r.scope)
}

func listFunctionIntents(ctx context.Context, stream jetstream.Stream, scope string) ([]LogEntry, error) {
	prefix := fmt.Sprintf("%s.%s.function.%s.", controlSubjectRoot, scope, MutationFunctionIntent)
	info, err := stream.Info(ctx, jetstream.WithSubjectFilter(prefix+">"))
	if err != nil {
		return nil, err
	}
	if err := verifyControlStreamConfig(info.Config, info.Config.Replicas); err != nil {
		return nil, err
	}
	if len(info.State.Subjects) > 10000 {
		return nil, ErrListTooLarge
	}
	keys := make([]string, 0, len(info.State.Subjects))
	for subject := range info.State.Subjects {
		key, ok := strings.CutPrefix(subject, prefix)
		if !ok || validateMutationKey(MutationFunctionIntent, key) != nil {
			return nil, errors.New("function log subject is invalid")
		}
		keys = append(keys, key)
	}
	slices.Sort(keys)
	entries := make([]LogEntry, 0, len(keys))
	for _, key := range keys {
		entry, err := readMutation(ctx, stream, scope, MutationFunctionIntent, key)
		if err != nil {
			return nil, err
		}
		if _, err := DecodeFunctionIntent(entry); err != nil {
			return nil, err
		}
		entries = append(entries, entry)
	}
	return entries, nil
}

func (c *Controller) Register(ctx context.Context, r Registration) (Receipt, error) {
	id := entityid.Derive("host", r.Cell, r.Node)
	if r.ID != "" && r.ID != id {
		return Receipt{}, errors.New("host ID differs from its node identity")
	}
	r.ID = id
	if err := validateRegistration(r, c.cell); err != nil {
		return Receipt{}, err
	}
	if r.ManagedOCI != nil && r.ManagedPlacement == nil {
		return Receipt{}, errors.New("managed host registration requires current schema-3 placement pins")
	}
	authorityEpoch := c.authorityEpoch()
	if err := c.guard(ctx, authorityEpoch); err != nil {
		return Receipt{}, err
	}
	if r.ManagedMember != nil {
		if c.managedEffectGate == nil || r.ManagedPlacement == nil {
			return Receipt{}, errors.New("managed host registration requires a terminal effect gate and placement scope")
		}
		release, err := c.managedEffectGate(ctx, authorityEpoch, authority.WorkloadScope{
			DatabaseID: r.ManagedPlacement.DatabaseID, PartitionID: r.ManagedPlacement.PartitionID,
		})
		if err != nil {
			return Receipt{}, err
		}
		defer release()
	}
	c.registrationMu.Lock()
	defer c.registrationMu.Unlock()
	payload, operationID, err := mutationPayload(r)
	if err != nil {
		return Receipt{}, err
	}
	key := registrationSubjectKey(c.cell, r.Node)
	for range 8 {
		if r.ManagedMember != nil {
			if c.managedVerifier == nil {
				return Receipt{}, errors.New("managed host registration requires a current placement verifier")
			}
			if err := c.managedVerifier.VerifyManagedRegistration(ctx, r); err != nil {
				return Receipt{}, fmt.Errorf("verify managed host registration: %w", err)
			}
			if err := c.requireExclusiveManagedMember(ctx, r); err != nil {
				return Receipt{}, err
			}
		}
		current, revision, exists, err := c.readRegistration(ctx, r.Node)
		if err != nil {
			return Receipt{}, err
		}
		if exists {
			if (current.ManagedOCI == nil) != (r.ManagedOCI == nil) ||
				current.ManagedOCI != nil && (current.ManagedMember == nil || *current.ManagedOCI != *r.ManagedOCI ||
					*current.ManagedMember != *r.ManagedMember || current.FailureDomain != r.FailureDomain) {
				return Receipt{}, errors.New("host managed binding cannot be retargeted")
			}
			if r.Generation < current.Generation {
				return Receipt{}, errors.New("registration generation moved backward")
			}
			if r.Generation == current.Generation {
				if !sameJSON(r, current) {
					return Receipt{}, errors.New("registration changed without a generation increase")
				}
				return Receipt{r.Generation, revision}, nil
			}
		}
		if err := c.guard(ctx, authorityEpoch); err != nil {
			return Receipt{}, err
		}
		written, err := c.mutations.CommitHostMutation(ctx, authorityEpoch, authority.MutationRegistration, key, operationID, revision, payload)
		if err == nil {
			return Receipt{r.Generation, written}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return Receipt{}, err
		}
	}
	return Receipt{}, errors.New("registration contention")
}

func (c *Controller) markRetired(ctx context.Context, epoch uint64, node string, retired bool) error {
	if err := c.guard(ctx, epoch); err != nil {
		return err
	}
	data, operation, err := mutationPayload(retirement{Retired: retired})
	if err != nil {
		return err
	}
	for range 8 {
		mark, revision, err := c.readRetirement(ctx, node)
		if err != nil {
			return err
		}
		if mark.Retired == retired {
			return nil
		}
		_, err = c.mutations.CommitHostMutation(ctx, epoch, authority.MutationRetirement, registrationSubjectKey(c.cell, node), operation, revision, data)
		if err == nil {
			return nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return fmt.Errorf("mark %s retired=%t: %w", node, retired, err)
		}
	}
	return errors.New("host retirement contention")
}

// RetireIdle retires node if it holds no active allocation and reports
// whether it did. A retired node takes no new allocation until Unretire,
// also from a later leader: the mark is in the log and every desired
// commit reads it. Withdrawals still apply. The process lock excludes desired
// commits during the idle check; the captured epoch fences leadership changes.
func (c *Controller) RetireIdle(ctx context.Context, node string) (bool, error) {
	c.retireMu.Lock()
	defer c.retireMu.Unlock()
	epoch := c.authorityEpoch()
	if err := c.guard(ctx, epoch); err != nil {
		return false, err
	}
	desired, err := c.ListDesired(ctx, "")
	if err != nil {
		return false, err
	}
	for _, d := range desired {
		if d.Node == node && !d.Withdrawn {
			return false, nil
		}
	}
	if err := c.markRetired(ctx, epoch, node, true); err != nil {
		return false, err
	}
	return true, nil
}

func (c *Controller) controlLogSubjects(ctx context.Context, filter string) (*jetstream.StreamInfo, error) {
	if err := c.lockControlLog(ctx); err != nil {
		return nil, err
	}
	defer func() { <-c.controlLogInfoGate }()
	return c.controlLog.Info(ctx, jetstream.WithSubjectFilter(filter))
}

func (c *Controller) ListHosts(ctx context.Context) ([]HostStatus, error) {
	if c.controlLog == nil {
		return nil, errors.New("ordered control log is required for host discovery")
	}
	prefix := protocol.Control(c.cell, "host", "registration", c.cell) + "."
	info, err := c.controlLogSubjects(ctx, prefix+"*")
	if err != nil {
		return nil, err
	}
	var hosts []HostStatus
	for subject := range info.State.Subjects {
		node, ok := strings.CutPrefix(subject, prefix)
		if !ok || validateToken(node, "node") != nil {
			return nil, errors.New("host registration subject is invalid")
		}
		r, registrationRevision, exists, err := c.readRegistration(ctx, node)
		if err != nil {
			return nil, err
		} else if !exists {
			continue
		}
		retirement, retirementRevision, err := c.readRetirement(ctx, node)
		if err != nil {
			return nil, err
		}
		status := HostStatus{Registration: r, Retired: retirement.Retired, Verified: !c.readOnly}
		s, _, exists, err := c.sessionSnapshot(ctx, sessionKey(c.cell, r.Node))
		if err != nil {
			return nil, err
		}
		if exists && s.RegistrationGeneration == r.Generation && time.Now().Before(s.ExpiresAt) {
			status.SessionExpiresAt = s.ExpiresAt
			for _, role := range r.Roles {
				report, _, ok, err := c.reportSnapshot(ctx, reportKey(c.cell, r.Node, role))
				if err != nil {
					return nil, err
				}
				if !ok || report.Cell != c.cell || report.Node != r.Node || report.Environment != r.Environment || report.Role != role ||
					report.SessionID != s.SessionID || report.Epoch != s.Epoch || time.Since(report.ObservedAt) >= ReportMaxAge || report.ObservedAt.After(time.Now().Add(maxClockSkew)) {
					continue
				}
				desired, desiredRevision, ok, err := c.readDesired(ctx, r.Node, role)
				if err != nil {
					return nil, err
				}
				if !ok || report.Generation != desired.Generation || report.Digest != desired.Digest || desired.Withdrawn && report.State == "running" ||
					validateManagedReportForDesired(report, desired) != nil {
					continue
				}
				confirmed, confirmedRevision, ok, err := c.readDesired(ctx, r.Node, role)
				if err != nil || !ok || confirmedRevision != desiredRevision || !sameJSON(confirmed, desired) {
					return nil, errors.New("desired changed during host status read")
				}
				check, _, ok, err := c.reportSnapshot(ctx, reportKey(c.cell, r.Node, role))
				if err != nil || !ok || check.ObservedAt.Before(report.ObservedAt) || !sameReportMeaning(check, report) ||
					check.SessionID != s.SessionID || check.Epoch != s.Epoch || check.Generation != desired.Generation || check.Digest != desired.Digest ||
					validateManagedReportForDesired(check, desired) != nil ||
					time.Since(check.ObservedAt) >= ReportMaxAge || check.ObservedAt.After(time.Now().Add(maxClockSkew)) || desired.Withdrawn && check.State == "running" {
					return nil, errors.New("report changed during host status read")
				}
				status.Reports = append(status.Reports, check)
			}
			check, _, ok, err := c.sessionSnapshot(ctx, sessionKey(c.cell, r.Node))
			if err != nil || !ok || check.RegistrationGeneration != r.Generation || check.SessionID != s.SessionID || check.Epoch != s.Epoch || !time.Now().Before(check.ExpiresAt) {
				return nil, errors.New("session changed during host status read")
			}
			status.SessionExpiresAt = check.ExpiresAt
		}
		confirmed, confirmedRevision, ok, err := c.readRegistration(ctx, node)
		if err != nil || !ok || confirmedRevision != registrationRevision || !sameJSON(confirmed, r) {
			return nil, errors.New("registration changed during host status read")
		}
		if _, revision, err := c.readRetirement(ctx, node); err != nil || revision != retirementRevision {
			return nil, errors.New("retirement changed during host status read")
		}
		hosts = append(hosts, status)
	}
	slices.SortFunc(hosts, func(a, b HostStatus) int { return strings.Compare(a.Registration.Node, b.Registration.Node) })
	return hosts, nil
}

func (c *Controller) readRetirement(ctx context.Context, node string) (retirement, uint64, error) {
	if err := validateToken(node, "node"); err != nil {
		return retirement{}, 0, err
	}
	key := registrationSubjectKey(c.cell, node)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationRetirement, key)
	if errors.Is(err, authority.ErrNotFound) {
		return retirement{}, 0, nil
	}
	if err != nil {
		return retirement{}, 0, err
	}
	if entry.Kind != authority.MutationRetirement || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return retirement{}, 0, errors.New("retirement log entry is malformed")
	}
	mark, err := decodeRetirement(entry.Payload)
	if err != nil {
		return retirement{}, 0, err
	}
	return mark, entry.Sequence, nil
}

func decodeRetirement(payload []byte) (retirement, error) {
	var value struct {
		Retired *bool `json:"retired"`
	}
	if err := decodeStrict(payload, &value); err != nil {
		return retirement{}, err
	}
	if value.Retired == nil {
		return retirement{}, errors.New("retirement record requires a non-null retired state")
	}
	return retirement{Retired: *value.Retired}, nil
}

func (c *Controller) readRegistration(ctx context.Context, node string) (Registration, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Registration{}, 0, false, err
	}
	key := registrationSubjectKey(c.cell, node)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationRegistration, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Registration{}, 0, false, nil
	}
	if err != nil {
		return Registration{}, 0, false, err
	}
	if entry.Kind != authority.MutationRegistration || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Registration{}, 0, false, errors.New("registration log entry is malformed")
	}
	var r Registration
	if err := decodeStrict(entry.Payload, &r); err != nil {
		return Registration{}, 0, false, err
	}
	if r.Node != node || r.ID != entityid.Derive("host", c.cell, node) {
		return Registration{}, 0, false, errors.New("registration log identity mismatch")
	}
	if err := validateRegistration(r, c.cell); err != nil {
		return Registration{}, 0, false, err
	}
	return r, entry.Sequence, true, nil
}

type functionPublicationSigner struct {
	claim       release.FunctionClaim
	module      []byte
	roots       trust.Keyring
	root        ed25519.PrivateKey
	leaf        ed25519.PrivateKey
	delegation  trust.Envelope
	factory     *ociclient.Factory
	allocations release.SequenceLocation
}

func newFunctionPublicationSigner(t *testing.T) functionPublicationSigner {
	t.Helper()
	module, err := hex.DecodeString("0061736d0100000001040160000003020100070a01065f737461727400000a040102000b")
	if err != nil {
		t.Fatal(err)
	}
	digest := sha256.Sum256(module)
	claim := release.FunctionClaim{Schema: release.FunctionSchema, ABI: release.FunctionABI,
		TenantID: entityid.Derive("tenant", "function-controller"), FunctionID: "echo", Revision: "first",
		Digest: hex.EncodeToString(digest[:]), Bytes: int64(len(module)), Environment: "canary", Cell: "GRU", Sequence: 42}
	root, rootPrivate, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	leafPublic, leaf, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(leafPublic)
	if err != nil {
		t.Fatal(err)
	}
	publicKey, err := trust.EncodeDelegatedPublicKey(leafPublic)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC().Truncate(time.Second)
	scope := release.FunctionScope(claim)
	delegation, err := trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion,
		SubjectKeyID: keyID, SubjectPublicKey: publicKey,
		Capabilities: []trust.Capability{{Domain: scope.Domain, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
			Environment: scope.Environment, Role: scope.Role, Slots: []string{scope.Slot}, Actions: []string{"sign"}}},
	}, now.Add(-time.Minute), now.Add(2*time.Hour), rootPrivate)
	if err != nil {
		t.Fatal(err)
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		t.Fatal(err)
	}
	factory, allocations := functionAllocationStore(t)
	return functionPublicationSigner{claim: claim, module: module, roots: roots, root: rootPrivate, leaf: leaf, delegation: delegation,
		factory: factory, allocations: allocations}
}

func (signer functionPublicationSigner) proof(t *testing.T, sequence uint64, revision string) release.VerifiedFunction {
	t.Helper()
	claim := signer.claim
	claim.Sequence, claim.Revision = sequence, revision
	now := time.Now().UTC().Truncate(time.Second)
	envelope, err := release.SignFunctionClaim(claim, signer.module, signer.delegation, signer.roots, signer.leaf, now, time.Hour)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	delegation, err := trust.EncodeEnvelope(signer.delegation)
	if err != nil {
		t.Fatal(err)
	}
	proof, err := release.VerifyFunctionCurrent(wire, delegation, signer.module, signer.roots,
		release.FunctionExpectation{Environment: claim.Environment, Cell: claim.Cell, TenantID: claim.TenantID,
			FunctionID: claim.FunctionID, Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: sequence}, now)
	if err != nil {
		t.Fatal(err)
	}
	return proof
}

func functionAllocationStore(t *testing.T) (*ociclient.Factory, release.SequenceLocation) {
	t.Helper()
	directory := t.TempDir()
	var lock sync.Mutex
	server := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !strings.HasPrefix(r.Header.Get("Authorization"), "Signature ") {
			http.Error(w, "unsigned OCI request", http.StatusUnauthorized)
			return
		}
		if !strings.HasPrefix(r.URL.Path, "/n/function-controller-test/b/gru-1-head/o/") {
			http.NotFound(w, r)
			return
		}
		nameSHA := sha256.Sum256([]byte(r.URL.Path))
		name := filepath.Join(directory, hex.EncodeToString(nameSHA[:]))
		lock.Lock()
		defer lock.Unlock()
		current, err := os.ReadFile(name)
		if err != nil && !errors.Is(err, os.ErrNotExist) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		found := err == nil
		etag := fmt.Sprintf(`"%x"`, sha256.Sum256(current))
		switch r.Method {
		case http.MethodGet:
			if !found {
				http.NotFound(w, r)
				return
			}
			w.Header().Set("ETag", etag)
			_, _ = w.Write(current)
		case http.MethodPut:
			if r.Header.Get("If-None-Match") == "*" && found || r.Header.Get("If-Match") != "" && (!found || r.Header.Get("If-Match") != etag) {
				w.WriteHeader(http.StatusPreconditionFailed)
				return
			}
			if r.Header.Get("If-Match") == "" && r.Header.Get("If-None-Match") != "*" {
				http.Error(w, "missing CAS", http.StatusBadRequest)
				return
			}
			body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 64<<10))
			if err != nil {
				http.Error(w, err.Error(), http.StatusBadRequest)
				return
			}
			if err := os.WriteFile(name, body, 0600); err != nil {
				http.Error(w, err.Error(), http.StatusInternalServerError)
				return
			}
			w.WriteHeader(http.StatusOK)
		default:
			w.WriteHeader(http.StatusMethodNotAllowed)
		}
	}))
	t.Cleanup(server.Close)
	previous := http.DefaultTransport
	transport := previous.(*http.Transport).Clone()
	transport.Proxy = nil
	tlsDialer := tls.Dialer{Config: server.Client().Transport.(*http.Transport).TLSClientConfig.Clone()}
	transport.DialTLSContext = func(ctx context.Context, network, address string) (net.Conn, error) {
		if address != "objectstorage.sa-saopaulo-1.oraclecloud.com:443" {
			return nil, fmt.Errorf("unexpected OCI endpoint %q", address)
		}
		return tlsDialer.DialContext(ctx, network, server.Listener.Addr().String())
	}
	transport.DialContext = func(context.Context, string, string) (net.Conn, error) {
		return nil, errors.New("allocation fixture requires its TLS OCI endpoint")
	}
	// The SDK must retain the local transport when production creates fresh clients.
	t.Setenv(common.UsingExpectHeaderEnvVar, "false")
	http.DefaultTransport = transport
	t.Cleanup(func() {
		http.DefaultTransport = previous
		transport.CloseIdleConnections()
	})
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	keyPEM := pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})
	factory, err := ociclient.New(common.NewRawConfigurationProvider("tenancy", "user", "sa-saopaulo-1", "fingerprint", string(keyPEM), nil),
		ociclient.Options{Region: "sa-saopaulo-1", Retry: ociclient.RetryOptions{MaxAttempts: 1}})
	if err != nil {
		t.Fatal(err)
	}
	client, err := factory.ObjectStorage()
	if err != nil {
		t.Fatal(err)
	}
	return factory, release.SequenceLocation{Client: client, Namespace: "function-controller-test", Bucket: "gru-1-head"}
}

func (s *Server) ListServices(_ context.Context, request *api.ListServicesRequest) (*api.ListServicesResponse, error) {
	var (
		services []*api.Service
		err      error
	)

	s.store.View(func(tx store.ReadTx) {
		switch {
		case request.Filters != nil && len(request.Filters.Names) > 0:
			services, err = store.FindServices(tx, buildFilters(store.ByName, request.Filters.Names))
		case request.Filters != nil && len(request.Filters.NamePrefixes) > 0:
			services, err = store.FindServices(tx, buildFilters(store.ByNamePrefix, request.Filters.NamePrefixes))
		case request.Filters != nil && len(request.Filters.IDPrefixes) > 0:
			services, err = store.FindServices(tx, buildFilters(store.ByIDPrefix, request.Filters.IDPrefixes))
		case request.Filters != nil && len(request.Filters.Runtimes) > 0:
			services, err = store.FindServices(tx, buildFilters(store.ByRuntime, request.Filters.Runtimes))
		default:
			services, err = store.FindServices(tx, store.All)
		}
	})
	if err != nil {
		switch err {
		case store.ErrInvalidFindBy:
			return nil, status.Error(codes.InvalidArgument, err.Error())
		default:
			return nil, err
		}
	}

	if request.Filters != nil {
		services = filterServices(services,
			func(e *api.Service) bool {
				return filterContains(e.Spec.Annotations.Name, request.Filters.Names)
			},
			func(e *api.Service) bool {
				return filterContainsPrefix(e.Spec.Annotations.Name, request.Filters.NamePrefixes)
			},
			func(e *api.Service) bool {
				return filterContainsPrefix(e.ID, request.Filters.IDPrefixes)
			},
			func(e *api.Service) bool {
				return filterMatchLabels(e.Spec.Annotations.Labels, request.Filters.Labels)
			},
			func(e *api.Service) bool {
				if len(request.Filters.Runtimes) == 0 {
					return true
				}
				r, err := naming.Runtime(e.Spec.Task)
				if err != nil {
					return false
				}
				return filterContains(r, request.Filters.Runtimes)
			},
		)
	}

	return &api.ListServicesResponse{
		Services: services,
	}, nil
}

func (s *Server) ListTasks(_ context.Context, request *api.ListTasksRequest) (*api.ListTasksResponse, error) {
	var (
		tasks []*api.Task
		err   error
	)

	s.store.View(func(tx store.ReadTx) {
		switch {
		case request.Filters != nil && len(request.Filters.Names) > 0:
			tasks, err = store.FindTasks(tx, buildFilters(store.ByName, request.Filters.Names))
		case request.Filters != nil && len(request.Filters.NamePrefixes) > 0:
			tasks, err = store.FindTasks(tx, buildFilters(store.ByNamePrefix, request.Filters.NamePrefixes))
		case request.Filters != nil && len(request.Filters.IDPrefixes) > 0:
			tasks, err = store.FindTasks(tx, buildFilters(store.ByIDPrefix, request.Filters.IDPrefixes))
		case request.Filters != nil && len(request.Filters.ServiceIDs) > 0:
			tasks, err = store.FindTasks(tx, buildFilters(store.ByServiceID, request.Filters.ServiceIDs))
		case request.Filters != nil && len(request.Filters.Runtimes) > 0:
			tasks, err = store.FindTasks(tx, buildFilters(store.ByRuntime, request.Filters.Runtimes))
		case request.Filters != nil && len(request.Filters.NodeIDs) > 0:
			tasks, err = store.FindTasks(tx, buildFilters(store.ByNodeID, request.Filters.NodeIDs))
		case request.Filters != nil && len(request.Filters.DesiredStates) > 0:
			filters := make([]store.By, 0, len(request.Filters.DesiredStates))
			for _, v := range request.Filters.DesiredStates {
				filters = append(filters, store.ByDesiredState(v))
			}
			tasks, err = store.FindTasks(tx, store.Or(filters...))
		default:
			tasks, err = store.FindTasks(tx, store.All)
		}

		if err != nil || request.Filters == nil {
			return
		}

		tasks = filterTasks(tasks,
			func(e *api.Task) bool {
				return filterContains(naming.Task(e), request.Filters.Names)
			},
			func(e *api.Task) bool {
				return filterContainsPrefix(naming.Task(e), request.Filters.NamePrefixes)
			},
			func(e *api.Task) bool {
				return filterContainsPrefix(e.ID, request.Filters.IDPrefixes)
			},
			func(e *api.Task) bool {
				return filterMatchLabels(e.ServiceAnnotations.Labels, request.Filters.Labels)
			},
			func(e *api.Task) bool {
				return filterContains(e.ServiceID, request.Filters.ServiceIDs)
			},
			func(e *api.Task) bool {
				return filterContains(e.NodeID, request.Filters.NodeIDs)
			},
			func(e *api.Task) bool {
				if len(request.Filters.Runtimes) == 0 {
					return true
				}
				r, err := naming.Runtime(e.Spec)
				if err != nil {
					return false
				}
				return filterContains(r, request.Filters.Runtimes)
			},
			func(e *api.Task) bool {
				if len(request.Filters.DesiredStates) == 0 {
					return true
				}
				for _, c := range request.Filters.DesiredStates {
					if c == e.DesiredState {
						return true
					}
				}
				return false
			},
			func(e *api.Task) bool {
				if !request.Filters.UpToDate {
					return true
				}

				service := store.GetService(tx, e.ServiceID)
				if service == nil {
					return false
				}

				n := store.GetNode(tx, e.NodeID)
				return !orchestrator.IsTaskDirty(service, e, n)
			},
		)
	})

	if err != nil {
		return nil, err
	}

	return &api.ListTasksResponse{
		Tasks: tasks,
	}, nil
}

func (s *Server) GetNode(_ context.Context, request *api.GetNodeRequest) (*api.GetNodeResponse, error) {
	if request.NodeID == "" {
		return nil, status.Error(codes.InvalidArgument, errInvalidArgument.Error())
	}

	var node *api.Node
	s.store.View(func(tx store.ReadTx) {
		node = store.GetNode(tx, request.NodeID)
	})
	if node == nil {
		return nil, status.Errorf(codes.NotFound, "node %s not found", request.NodeID)
	}

	if s.raft != nil {
		memberlist := s.raft.GetMemberlist()
		for _, member := range memberlist {
			if member.NodeID == node.ID {
				node.ManagerStatus = &api.ManagerStatus{
					RaftID:       member.RaftID,
					Addr:         member.Addr,
					Leader:       member.Status.Leader,
					Reachability: member.Status.Reachability,
				}
				break
			}
		}
	}

	return &api.GetNodeResponse{
		Node: node,
	}, nil
}

