func validateAutoscaleConfig(config *AutoscaleConfig, profiles map[string]WorkloadProfile) error {
	if config == nil {
		return nil
	}
	if err := workload.ValidateSpecs(config.Services); err != nil {
		return fmt.Errorf("autoscale services: %w", err)
	}
	for _, spec := range config.Services {
		if spec.Kind != workload.KindStateless {
			// Nothing reconciles stateful services yet (TerraBase is sized
			// by placement); refuse signed config that would silently do
			// nothing.
			return fmt.Errorf("autoscale service %q: stateful services are not reconciled yet", spec.Role)
		}
		if spec.Scaling != nil {
			for _, signal := range spec.Scaling.Signals {
				if !hostload.StatelessSignal(signal.Name) {
					// Request rates and TerraBase signals have no producer
					// for the stateless services this reconciler owns.
					return fmt.Errorf("autoscale service %q: signal %q has no producer for stateless services", spec.Role, signal.Name)
				}
			}
		}
		if spec.Role == "terrabase" {
			// TerraBase members are owned by placement, never by the
			// stateless reconciler or release shaping.
			return fmt.Errorf("autoscale service %q is a managed TerraBase role", spec.Role)
		}
		// ts-auth runs exactly its replica count, or none while a cell spec
		// drains it before removing it.
		if spec.Role == tsauth.Role && (spec.Replicas != workload.ReplicaBounds{Min: tsauth.Replicas, Max: tsauth.Replicas} &&
			spec.Replicas != workload.ReplicaBounds{} || spec.Placement.MaxPerFailureDomain != 1) {
			return fmt.Errorf("autoscale service %q must keep exactly %d replicas (or 0 to drain it) with one per failure domain",
				spec.Role, tsauth.Replicas)
		}
		profile, exists := profiles[spec.Role]
		if !exists {
			return fmt.Errorf("autoscale service %q has no workload profile", spec.Role)
		}
		if spec.Resources != (placement.Resources{}) && spec.Resources != profile.Resources {
			return fmt.Errorf("autoscale service %q resources differ from its workload profile", spec.Role)
		}
	}
	return nil
}

// startWorkloadAutoscale retains the native transition observer until manager replacement is qualified.
func startWorkloadAutoscale(cell string, config *AutoscaleConfig, profiles map[string]WorkloadProfile,
	specs []workload.ServiceSpec, hosts *host.Controller,
	fencer authority.Fencer,
	nativeReleases *nativeHistory,
) (*workload.Reconciler, *hostTelemetry, error) {
	resources := profileResources(profiles)
	requests := loadRequests(resources)
	load := &hostTelemetry{fencer: fencer, requests: requests,
		load: hostload.NewAggregator(hostload.AggregatorConfig{Requests: requests})}
	var releaseResources func(context.Context, []host.Desired, map[string]placement.Resources) (map[string]placement.Resources, error)
	var writer workload.DesiredWriter = hosts
	if nativeReleases != nil {
		releaseResources = func(ctx context.Context, desired []host.Desired, profiles map[string]placement.Resources) (map[string]placement.Resources, error) {
			resolved, err := nativeReleases.resources(ctx, desired, profiles)
			if err == nil {
				load.setResources(resolved)
			}
			return resolved, err
		}
		writer = nativeReleases
	}
	reconciler, err := workload.New(workload.Config{Cell: cell, Specs: specs, Profiles: resources, ReleaseResources: releaseResources,
		Hosts: hosts, Writer: writer, Fencer: fencer, Signals: load.load,
		Logf: log.Printf})
	if err != nil {
		return nil, nil, fmt.Errorf("start workload reconciler: %w", err)
	}
	hosts.SetLoadSink(load.record)
	return reconciler, load, nil
}

func loadRequests(resources map[string]placement.Resources) map[string]hostload.Request {
	requests := make(map[string]hostload.Request, len(resources))
	for role, request := range resources {
		requests[role] = hostload.Request{CPUCores: float64(request.CPU), MemoryBytes: request.MemoryBytes}
	}
	return requests
}

func unownedShape(intent delivery.Intent, observation workload.Observation) (delivery.PlanShape, error) {
	if !observation.Shaped() {
		return delivery.PlanShape{Generation: intent.Generation, Replicas: intent.DesiredReplicas}, nil
	}
	generation, err := workload.ReleaseGeneration(intent.Generation)
	return delivery.PlanShape{Generation: generation, Replicas: intent.DesiredReplicas}, err
}

func releasePlacementDomainCap(role string) int {
	if role == tsauth.Role {
		return 1
	}
	return 0
}

// Shaped reports whether the role has ever been committed with a
// release-scoped generation (see ReleaseShift) on any node. Such a role must
// stay in that generation space even after the reconciler stops owning it:
// a plain intent generation would move every host backwards.
func (o Observation) Shaped() bool {
	for _, generation := range o.NodeHighWater {
		if ReleaseOf(generation) > 0 {
			return true
		}
	}
	return false
}

const ReleaseShift = 24

const maxRelease = uint64(1)<<(64-ReleaseShift) - 1

var (
	ErrNoRelease         = errors.New("workload has no active release to reconcile")
	ErrGenerationSpace   = errors.New("workload release generation space is exhausted")
	ErrReleaseSuperseded = errors.New("workload release has no active replicas")
)

// ReleaseGeneration is the first desired generation of a reconciled release.
func ReleaseGeneration(release uint64) (uint64, error) {
	if release == 0 || release > maxRelease {
		return 0, fmt.Errorf("%w: release generation %d", ErrGenerationSpace, release)
	}
	return release << ReleaseShift, nil
}

// ReleaseOf returns the release part of a desired generation.
func ReleaseOf(generation uint64) uint64 { return generation >> ReleaseShift }

func ValidateSpecs(specs []ServiceSpec) error {
	seen := make(map[string]struct{}, len(specs))
	for _, spec := range specs {
		if err := spec.Validate(); err != nil {
			return fmt.Errorf("service %q: %w", spec.Role, err)
		}
		if _, exists := seen[spec.Role]; exists {
			return fmt.Errorf("%w: repeated role %q", ErrInvalidSpec, spec.Role)
		}
		seen[spec.Role] = struct{}{}
	}
	return nil
}

// EncodeJSON emits deterministic JSON. Deterministic map ordering keeps a given Go
// value's wire representation stable; signed payloads are also compacted before
// their digest is calculated.
func EncodeJSON(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode protocol JSON: %w", err)
	}
	return encoded, nil
}

// DecodeStrict decodes one bounded JSON value, rejecting duplicate names, invalid
// UTF-8, and unknown struct members. The Go 1.27 JSON v2 decoder rejects duplicate
// object names and invalid UTF-8 by default; RejectUnknownMembers closes the
// remaining permissive struct-decoding path.
func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

