func ReadVerified(ctx context.Context, js jetstream.JetStream, store interface {
	GetInfo(context.Context, string, ...jetstream.GetObjectInfoOpt) (*jetstream.ObjectInfo, error)
}, bucket, name, digest string, signedSize, maxBytes int64, dst io.Writer) error {
	if js == nil || store == nil || dst == nil || signedSize <= 0 || signedSize > maxBytes || len(digest) != 64 {
		return fmt.Errorf("%w: reader arguments", ErrInvalid)
	}
	info, err := store.GetInfo(ctx, name)
	if err != nil {
		return fmt.Errorf("inspect artifact: %w", err)
	}
	if err := validateMetadata(info, bucket, name, signedSize); err != nil {
		return err
	}
	stream, err := js.Stream(ctx, "OBJ_"+bucket)
	if err != nil {
		return fmt.Errorf("bind artifact readback stream: %w", err)
	}
	return verifyChunks(ctx, info, bucket, digest, signedSize, dst, func(ctx context.Context, sequence uint64, subject string) (*jetstream.RawStreamMsg, error) {
		return stream.GetMsg(ctx, sequence, jetstream.WithGetMsgSubject(subject))
	})
}

// ReadVerifiedAuthoritative verifies captured leader metadata using standard
// MSG.GET chunk reads, so a stale replica cannot authorize corruption repair.
// Callers must discard dst if this function returns an error.
func ReadVerifiedAuthoritative(ctx context.Context, js jetstream.JetStream, info *jetstream.ObjectInfo,
	bucket, name, digest string, signedSize, maxBytes int64, dst io.Writer,
) error {
	if js == nil || js.Conn() == nil || dst == nil || signedSize <= 0 || signedSize > maxBytes || len(digest) != 64 {
		return fmt.Errorf("%w: reader arguments", ErrInvalid)
	}
	if err := validateMetadata(info, bucket, name, signedSize); err != nil {
		return err
	}
	options := js.Options()
	prefix := options.APIPrefix
	if options.Domain != "" {
		prefix = "$JS." + options.Domain + ".API."
	} else if prefix == "" {
		prefix = jetstream.DefaultAPIPrefix
	}
	apiSubject := strings.TrimSuffix(prefix, ".") + ".STREAM.MSG.GET.OBJ_" + bucket
	if _, bounded := ctx.Deadline(); !bounded && options.DefaultTimeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, options.DefaultTimeout)
		defer cancel()
	}
	return verifyChunks(ctx, info, bucket, digest, signedSize, dst, func(ctx context.Context, sequence uint64, subject string) (*jetstream.RawStreamMsg, error) {
		request, err := json.Marshal(struct {
			Sequence uint64 `json:"seq"`
			Subject  string `json:"next_by_subj"`
		}{sequence, subject})
		if err != nil {
			return nil, err
		}
		message, err := js.Conn().RequestWithContext(ctx, apiSubject, request)
		if err != nil {
			return nil, err
		}
		var response struct {
			Error   *jetstream.APIError `json:"error"`
			Message *struct {
				Subject  string `json:"subject"`
				Sequence uint64 `json:"seq"`
				Data     []byte `json:"data"`
			} `json:"message"`
		}
		if err := json.Unmarshal(message.Data, &response); err != nil {
			return nil, err
		}
		if response.Error != nil {
			return nil, response.Error
		}
		if response.Message == nil {
			return nil, jetstream.ErrInvalidJetStreamResponse
		}
		return &jetstream.RawStreamMsg{Subject: response.Message.Subject, Sequence: response.Message.Sequence,
			Data: response.Message.Data}, nil
	})
}

func validateMetadata(info *jetstream.ObjectInfo, bucket, name string, signedSize int64) error {
	if info == nil || info.Name != name || info.Bucket != bucket || info.Deleted ||
		info.Opts != nil && info.Opts.Link != nil || info.Size != uint64(signedSize) ||
		info.NUID == "" || info.Chunks == 0 || uint64(info.Chunks) > uint64(signedSize) {
		return fmt.Errorf("%w: artifact object metadata", ErrInvalid)
	}
	return nil
}

func verifyChunks(ctx context.Context, info *jetstream.ObjectInfo, bucket, digest string, sizeLimit int64, dst io.Writer,
	get func(context.Context, uint64, string) (*jetstream.RawStreamMsg, error)) error {
	if info == nil || info.NUID == "" || info.Chunks == 0 || sizeLimit <= 0 ||
		uint64(info.Chunks) > uint64(sizeLimit) {
		return fmt.Errorf("%w: artifact chunk metadata", ErrInvalid)
	}
	storedDigest, err := jetstream.DecodeObjectDigest(info.Digest)
	if err != nil || len(storedDigest) != sha256.Size {
		return fmt.Errorf("%w: artifact object digest", ErrInvalid)
	}
	subject := "$O." + bucket + ".C." + info.NUID
	h := sha256.New()
	var size int64
	sequence := uint64(1)
	for range info.Chunks {
		if err := ctx.Err(); err != nil {
			return err
		}
		message, err := get(ctx, sequence, subject)
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			return fmt.Errorf("artifact chunk is not visible: %w", jetstream.ErrObjectNotFound)
		}
		if err != nil {
			return fmt.Errorf("read artifact chunk: %w", err)
		}
		if message == nil || message.Subject != subject || message.Sequence < sequence ||
			message.Sequence == ^uint64(0) || len(message.Data) == 0 || int64(len(message.Data)) > sizeLimit-size {
			return fmt.Errorf("%w: artifact chunk sequence or size", ErrInvalid)
		}
		if _, err := dst.Write(message.Data); err != nil {
			return fmt.Errorf("spool artifact chunk: %w", err)
		}
		_, _ = h.Write(message.Data)
		size += int64(len(message.Data))
		sequence = message.Sequence + 1
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	extra, err := get(ctx, sequence, subject)
	if err == nil || extra != nil {
		return fmt.Errorf("%w: artifact has extra chunks", ErrInvalid)
	}
	if !errors.Is(err, jetstream.ErrMsgNotFound) {
		return fmt.Errorf("check artifact chunk count: %w", err)
	}
	actual := h.Sum(nil)
	if size != sizeLimit || hex.EncodeToString(actual) != digest || !bytes.Equal(actual, storedDigest) {
		return fmt.Errorf("%w: artifact bytes differ from signed digest", ErrInvalid)
	}
	return nil
}

func TestReadVerifiedAuthoritativeRequiresOnlyLeaderReadGrantIntegration(t *testing.T) {
	const bucket = "ARTIFACTS"
	srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true,
		StoreDir: t.TempDir(), Users: []*server.User{
			{Username: "admin", Password: "admin-secret"},
			{Username: "reader", Password: "reader-secret", Permissions: &server.Permissions{
				Publish:   &server.SubjectPermission{Allow: []string{"$JS.API.STREAM.MSG.GET.OBJ_" + bucket}},
				Subscribe: &server.SubjectPermission{Allow: []string{"_INBOX.>"}},
			}},
		}})
	if err != nil {
		t.Fatal(err)
	}
	go srv.Start()
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("NATS did not start")
	}
	t.Cleanup(func() { srv.Shutdown(); srv.WaitForShutdown() })
	admin, err := nats.Connect(srv.ClientURL(), nats.UserInfo("admin", "admin-secret"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(admin.Close)
	adminJS, err := jetstream.New(admin)
	if err != nil {
		t.Fatal(err)
	}
	store, err := adminJS.CreateObjectStore(t.Context(), jetstream.ObjectStoreConfig{Bucket: bucket})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := store.PutBytes(t.Context(), "unrelated", []byte("skip these chunk and metadata sequences")); err != nil {
		t.Fatal(err)
	}
	body := []byte("multiple pinned chunks")
	digest := sha256.Sum256(body)
	const name = "pinned"
	info, err := store.Put(t.Context(), jetstream.ObjectMeta{Name: name, Opts: &jetstream.ObjectMetaOptions{ChunkSize: 3}}, bytes.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	reader, err := nats.Connect(srv.ClientURL(), nats.UserInfo("reader", "reader-secret"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(reader.Close)
	readerJS, err := jetstream.New(reader)
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(t.Context(), time.Second)
	defer cancel()
	var output bytes.Buffer
	if err := artifact.ReadVerifiedAuthoritative(ctx, readerJS, info, bucket, name, hex.EncodeToString(digest[:]),
		int64(len(body)), 100, &output); err != nil || !bytes.Equal(output.Bytes(), body) {
		t.Fatalf("leader-only verification: bytes=%q error=%v", output.Bytes(), err)
	}

t.Run("replayed chunk reply", func(t *testing.T) {
	ctx, cancel := context.WithTimeout(t.Context(), time.Second)
	defer cancel()
	stream, err := adminJS.Stream(ctx, "OBJ_"+bucket)
	if err != nil {
		t.Fatal(err)
	}
	first, err := stream.GetMsg(ctx, 1, jetstream.WithGetMsgSubject("$O."+bucket+".C."+info.NUID))
	if err != nil {
		t.Fatal(err)
	}
	response, err := json.Marshal(map[string]any{"message": map[string]any{
		"subject": first.Subject, "seq": first.Sequence, "data": first.Data,
	}})
	if err != nil {
		t.Fatal(err)
	}
	// Replay a real stored chunk through the protocol boundary to exercise an untrusted stale reply.
	sub, err := admin.Subscribe("REPLAY.API.STREAM.MSG.GET.OBJ_"+bucket, func(message *nats.Msg) {
		if err := message.Respond(response); err != nil {
			t.Errorf("replay chunk: %v", err)
		}
	})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = sub.Unsubscribe() })
	if err := admin.Flush(); err != nil {
		t.Fatal(err)
	}
	replayedJS, err := jetstream.NewWithAPIPrefix(admin, "REPLAY.API")
	if err != nil {
		t.Fatal(err)
	}
	var output bytes.Buffer
	if err := artifact.ReadVerifiedAuthoritative(ctx, replayedJS, info, bucket, name, hex.EncodeToString(digest[:]),
		int64(len(body)), 100, &output); !errors.Is(err, artifact.ErrInvalid) {
		t.Fatalf("replayed nonadvancing sequence was accepted: %v", err)
	}
	if !bytes.Equal(output.Bytes(), first.Data) {
		t.Fatalf("replayed bytes reached destination: %q", output.Bytes())
	}
})

func TestReadVerifiedObjectStoreToFileIntegration(t *testing.T) {
	for _, scenario := range []string{
		"interleaved chunks", "zero-byte object", "missing chunk", "oversize chunk",
		"signed digest mismatch", "object digest mismatch", "extra chunk", "closed destination",
	} {
		t.Run(scenario, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
			defer cancel()
			srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true, StoreDir: t.TempDir()})
			if err != nil {
				t.Fatal(err)
			}
			go srv.Start()
			t.Cleanup(func() { srv.Shutdown(); srv.WaitForShutdown() })
			if !srv.ReadyForConnections(5 * time.Second) {
				t.Fatal("NATS did not start")
			}
			conn, err := nats.Connect(srv.ClientURL())
			if err != nil {
				t.Fatal(err)
			}
			t.Cleanup(conn.Close)
			js, err := jetstream.New(conn)
			if err != nil {
				t.Fatal(err)
			}
			const bucket = "ARTIFACTS"
			const name = "pinned"
			store, err := js.CreateObjectStore(ctx, jetstream.ObjectStoreConfig{Bucket: bucket, Storage: jetstream.FileStorage})
			if err != nil {
				t.Fatal(err)
			}
			body := []byte("firstmiddlelast")
			sum := sha256.Sum256(body)
			digest := hex.EncodeToString(sum[:])
			info, err := store.Put(ctx, jetstream.ObjectMeta{Name: name, Opts: &jetstream.ObjectMetaOptions{ChunkSize: 5}}, bytes.NewReader(body))
			if err != nil {
				t.Fatal(err)
			}
			stream, err := js.Stream(ctx, "OBJ_"+bucket)
			if err != nil {
				t.Fatal(err)
			}
			subject := "$O." + bucket + ".C." + info.NUID
			first, err := stream.GetMsg(ctx, 1, jetstream.WithGetMsgSubject(subject))
			if err != nil {
				t.Fatal(err)
			}
			wantError := artifact.ErrInvalid
			switch scenario {
			case "interleaved chunks":
				var chunks [][]byte
				for sequence := uint64(1); ; {
					message, err := stream.GetMsg(ctx, sequence, jetstream.WithGetMsgSubject(subject))
					if errors.Is(err, jetstream.ErrMsgNotFound) {
						break
					}
					if err != nil {
						t.Fatal(err)
					}
					chunks = append(chunks, message.Data)
					if err := stream.DeleteMsg(ctx, message.Sequence); err != nil {
						t.Fatal(err)
					}
					sequence = message.Sequence + 1
				}
				for _, chunk := range chunks {
					if _, err := js.Publish(ctx, subject, chunk); err != nil {
						t.Fatal(err)
					}
					if _, err := store.PutBytes(ctx, "unrelated", []byte("other object")); err != nil {
						t.Fatal(err)
					}
				}
				wantError = nil
			case "zero-byte object":
				if _, err := store.PutBytes(ctx, name, nil); err != nil {
					t.Fatal(err)
				}
			case "missing chunk":
				if err := stream.DeleteMsg(ctx, first.Sequence); err != nil {
					t.Fatal(err)
				}
				wantError = jetstream.ErrObjectNotFound
			case "oversize chunk":
				if _, err := js.Publish(ctx, subject, bytes.Repeat([]byte("x"), len(body)+1)); err != nil {
					t.Fatal(err)
				}
				if err := stream.DeleteMsg(ctx, first.Sequence); err != nil {
					t.Fatal(err)
				}
			case "signed digest mismatch":
				digest = strings.Repeat("0", 64)
			case "object digest mismatch":
				legacy, err := conn.JetStream()
				if err != nil {
					t.Fatal(err)
				}
				metadata, err := legacy.GetLastMsg("OBJ_"+bucket, "$O."+bucket+".M.>", nats.Context(ctx))
				if err != nil {
					t.Fatal(err)
				}
				info.Digest = "SHA-256=bad"
				data, err := json.Marshal(info)
				if err != nil {
					t.Fatal(err)
				}
				message := nats.NewMsg(metadata.Subject)
				message.Header.Set(nats.MsgRollup, nats.MsgRollupSubject)
				message.Data = data
				if _, err := js.PublishMsg(ctx, message); err != nil {
					t.Fatal(err)
				}
			case "extra chunk":
				if _, err := js.Publish(ctx, subject, []byte("extra")); err != nil {
					t.Fatal(err)
				}
			case "closed destination":
				wantError = os.ErrClosed
			}
			path := filepath.Join(t.TempDir(), "artifact")
			output, err := os.Create(path)
			if err != nil {
				t.Fatal(err)
			}
			t.Cleanup(func() { _ = output.Close() })
			if scenario == "closed destination" {
				if err := output.Close(); err != nil {
					t.Fatal(err)
				}
			}

