func (l *Loop) Run(ctx context.Context) error {
	ticker := time.NewTicker(Interval)
	defer ticker.Stop()
	for {
		l.tick(ctx, time.Now())
		select {
		case <-ctx.Done():
			return nil
		case <-ticker.C:
		}
	}
}

func (l *Loop) tick(ctx context.Context, now time.Time) {
	config, snapshot := l.Config(), l.Authority.Current()
	if config == nil || !snapshot.CanMutate() {
		l.follow()
		return
	}
	if l.since.IsZero() {
		l.since = now
	}
	err := l.publish(ctx, *config, now, snapshot.Epoch)
	if errors.Is(err, authority.ErrNotLeader) || errors.Is(err, authority.ErrFenced) {
		l.follow()
		return
	}
	if err == nil {
		if l.alerted {
			slog.InfoContext(ctx, "Atlas topology is current again", observability.ComponentKey, "atlas", observability.EventKey, true)
		}
		l.since, l.alerted = now, false
		return
	}
	if errors.Is(err, ErrUnauthorized) {
		l.Key = nil // re-read a rotated key
	}
	slog.WarnContext(ctx, "Atlas publish failed", observability.ComponentKey, "atlas", "error", err)
	if !l.alerted && now.Sub(l.since) >= StaleAfter {
		l.alerted = true
		slog.ErrorContext(ctx, "ALERT Atlas topology is stale: no publish succeeded", observability.ComponentKey, "atlas",
			"since", l.since, "error", err, observability.EventKey, true)
	}
}

// follow drops the job: another controller, or nobody, owns it, and it
// starts afresh if it comes back here.
func (l *Loop) follow() { l.since, l.alerted = time.Time{}, false }

// publish bounds the whole attempt, the key read included, by Interval, so
// a hung Vault read cannot hold the loop past StaleAfter without an alert.
func (l *Loop) publish(parent context.Context, config Config, now time.Time, epoch uint64) error {
	ctx, cancel := context.WithTimeout(parent, Interval)
	defer cancel()
	if l.Key == nil || l.ref != config.PublishKey {
		key, err := l.loadKey(parent, ctx, config.PublishKey)
		if err != nil {
			return err
		}
		l.Key, l.ref = key, config.PublishKey
	}
	return l.Publish(ctx, config, now, func(ctx context.Context) error { return l.Authority.Guard(ctx, epoch) })
}

// loadKey keeps one key read in flight and stops waiting for it at ctx's
// deadline even when the read ignores it: the instance principal's setup
// takes no context. Later attempts wait on the same read instead of starting
// another, so a stalled Vault or metadata service never piles reads up. The
// read runs on parent, bounded by StaleAfter, so a slow one can still finish.
func (l *Loop) loadKey(parent, ctx context.Context, ref vaultsecret.Ref) (*ecdsa.PrivateKey, error) {
	if l.reading == nil {
		read := &keyRead{ref: ref, done: make(chan keyResult, 1)}
		go func() {
			readCtx, cancel := context.WithTimeout(parent, StaleAfter)
			defer cancel()
			key, err := l.LoadKey(readCtx, ref)
			read.done <- keyResult{key, err}
		}()
		l.reading = read
	}
	select {
	case result := <-l.reading.done:
		read := l.reading
		l.reading = nil
		if read.ref != ref {
			return nil, errors.New("the atlas publish key ref changed during its read")
		}
		return result.key, result.err
	case <-ctx.Done():
		return nil, fmt.Errorf("read the atlas publish key: %w", ctx.Err())
	}
}

type fakeAuthority struct {
	leader bool
	guard  error
}

func (f *fakeAuthority) Current() authority.Snapshot {
	return authority.Snapshot{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Leader: f.leader, Ready: true, Epoch: 7, Revision: 1, ExpiresAt: time.Now().Add(time.Minute)}
}

func (f *fakeAuthority) Guard(_ context.Context, epoch uint64) error {
	if epoch != 7 {
		return authority.ErrFenced
	}
	return f.guard
}

atlaspublish.text:
func (p *Publisher) Publish(ctx context.Context, config Config, now time.Time, guard func(context.Context) error) error {
	doc := sdkatlas.Topology{V: 1, Updated: max(now.Unix(), p.last+1), Services: config.Services}
	doc.Regions = make([]sdkatlas.Region, len(config.Regions))
	var probes sync.WaitGroup
	for i, entry := range config.Regions {
		doc.Regions[i] = sdkatlas.Region{ID: entry.ID, Name: entry.Name, Country: entry.Country, Lat: entry.Lat, Lon: entry.Lon, API: entry.API, Auth: entry.Auth}
		probes.Go(func() { doc.Regions[i].OK = ready(ctx, p.HTTP, entry.API) })
	}
	probes.Wait()
	if guard != nil {
		if err := guard(ctx); err != nil {
			return err
		}
	}
	client := sdkatlas.Publisher{BaseURL: config.URL, Key: p.Key, HTTPClient: p.HTTP}
	report, err := client.Publish(ctx, sdkatlas.Document{Topology: &doc})
	if refused, ok := errors.AsType[*sdkatlas.Error](err); ok && refused.Status == http.StatusUnauthorized {
		return ErrUnauthorized
	}
	if err != nil {
		return err
	}
	if report.Topology != "updated" {
		return fmt.Errorf("atlas answered topology %q", report.Topology)
	}
	p.last = doc.Updated
	return nil
}

// ready is the region's GET <api>/readyz verdict.
func ready(ctx context.Context, client *http.Client, api string) bool {
	ctx, cancel := context.WithTimeout(ctx, probeTimeout)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, strings.TrimSuffix(api, "/")+"/readyz", nil)
	if err != nil {
		return false
	}
	response, err := client.Do(request)
	if err != nil {
		return false
	}
	_, _ = io.Copy(io.Discard, io.LimitReader(response.Body, 4096))
	_ = response.Body.Close()
	return response.StatusCode == http.StatusOK
}

func fakeAtlas(t *testing.T, publishKeys string, status *atomic.Int32, got *sdkatlas.Topology) *httptest.Server {
	var jwks struct {
		Keys []struct {
			X string `json:"x"`
			Y string `json:"y"`
		} `json:"keys"`
	}
	if err := json.Unmarshal([]byte(publishKeys), &jwks); err != nil || len(jwks.Keys) != 1 {
		t.Fatalf("PUBLISH_KEYS %s: %v", publishKeys, err)
	}
	x, _ := base64.RawURLEncoding.DecodeString(jwks.Keys[0].X)
	y, _ := base64.RawURLEncoding.DecodeString(jwks.Keys[0].Y)
	public, err := ecdsa.ParseUncompressedPublicKey(elliptic.P256(), append(append([]byte{4}, x...), y...))
	if err != nil {
		t.Fatal(err)
	}
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/readyz" {
			w.WriteHeader(int(status.Load()))
			return
		}
		if r.URL.Path != "/v1/publish" {
			http.Error(w, `{"error":{"code":"store_unavailable"}}`, http.StatusBadGateway)
			return
		}
		body, _ := io.ReadAll(r.Body)
		timestamp, signature := r.Header.Get("x-atlas-timestamp"), r.Header.Get("x-atlas-signature")
		raw, err := base64.RawURLEncoding.DecodeString(signature)
		digest := sha256.Sum256([]byte("atlas-publish-v1\n" + timestamp + "\n" + string(body)))
		if len(signature) != 86 || err != nil ||
			!ecdsa.Verify(public, digest[:], new(big.Int).SetBytes(raw[:32]), new(big.Int).SetBytes(raw[32:])) {
			http.Error(w, `{"error":{"code":"invalid_signature"}}`, http.StatusUnauthorized)
			return
		}
		var request struct {
			Topology sdkatlas.Topology `json:"topology"`
		}
		if err := json.Unmarshal(body, &request); err != nil {
			t.Error(err)
		}
		*got = request.Topology
		_, _ = io.WriteString(w, `{"topology":"updated","placements":[]}`)
	}))
}

func testConfig(t *testing.T) Config {
	data, err := os.ReadFile("../../deploy/oci-region/atlas-gru-1.json")
	if err != nil {
		t.Fatal(err)
	}
	var config Config
	if err := protocol.DecodeStrict(data, &config, 64<<10); err != nil {
		t.Fatal(err)
	}
	return config
}

func (p *Publisher) Publish(ctx context.Context, doc Document) (*Report, error) {
	for _, placement := range doc.Placements {
		if err := entityid.Check(placement.Project); err != nil {
			return nil, fmt.Errorf("atlas: publish request project ID: %w", err)
		}
	}
	base, err := url.Parse(p.BaseURL)
	if err != nil || base.Host == "" || base.User != nil || base.RawQuery != "" || base.ForceQuery || base.Fragment != "" ||
		(base.Path != "" && base.Path != "/") || (base.Scheme != "https" && !(base.Scheme == "http" && loopback(base.Hostname()))) {
		return nil, fmt.Errorf("atlas: BaseURL %q must be an https origin without a path", p.BaseURL)
	}
	endpoint := *base
	endpoint.Path, endpoint.RawPath = "/v1/publish", ""
	body, err := json.Marshal(doc)
	if err != nil {
		return nil, fmt.Errorf("atlas: encode document: %w", err)
	}
	timestamp := strconv.FormatInt(time.Now().Unix(), 10)
	signature, err := Sign(p.Key, timestamp, body)
	if err != nil {
		return nil, err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint.String(), bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("X-Atlas-Timestamp", timestamp)
	req.Header.Set("X-Atlas-Signature", signature)
	hc := http.Client{Timeout: 30 * time.Second}
	if p.HTTPClient != nil {
		hc = *p.HTTPClient
	}
	// A redirect would carry the signed body and headers to another origin.
	hc.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	res, err := hc.Do(req)
	if err != nil {
		return nil, fmt.Errorf("atlas: publish: %w", err)
	}
	defer res.Body.Close()
	answer, err := io.ReadAll(io.LimitReader(res.Body, 64<<10))
	if err != nil {
		return nil, fmt.Errorf("atlas: read publish response: %w", err)
	}
	if res.StatusCode != http.StatusOK {
		e := &Error{Status: res.StatusCode}
		var env struct{ Error *Error }
		if json.Unmarshal(answer, &env) == nil && env.Error != nil {
			e.Code, e.Message, e.Fix = env.Error.Code, env.Error.Message, env.Error.Fix
		}
		return nil, e
	}
	var report Report
	if err := json.Unmarshal(answer, &report); err != nil {
		return nil, fmt.Errorf("atlas: decode publish response: %w", err)
	}
	for _, placement := range report.Placements {
		if err := entityid.Check(placement.Project); err != nil {
			return nil, fmt.Errorf("atlas: publish response project ID: %w", err)
		}
	}
	return &report, nil
}

// Sign is X-Atlas-Signature: base64url of the raw r||s ES256 signature over
// "atlas-publish-v1\n<timestamp>\n<body>".
func Sign(key *ecdsa.PrivateKey, timestamp string, body []byte) (string, error) {
	if key == nil || key.Curve != elliptic.P256() {
		return "", errors.New("atlas: the publish key must be a P-256 key")
	}
	digest := sha256.Sum256(slices.Concat([]byte("atlas-publish-v1\n"+timestamp+"\n"), body))
	r, s, err := ecdsa.Sign(rand.Reader, key, digest[:])
	if err != nil {
		return "", fmt.Errorf("atlas: sign: %w", err)
	}
	raw := make([]byte, 64)
	r.FillBytes(raw[:32])
	s.FillBytes(raw[32:])
	return base64.RawURLEncoding.EncodeToString(raw), nil
}

func loopback(host string) bool {
	ip := net.ParseIP(host)
	return host == "localhost" || ip != nil && ip.IsLoopback()
}

