func (d Discovery) ServingCells(now time.Time) ([]string, error) {
	if d.V != 1 || len(d.Regions) == 0 || len(d.Regions) > catalog.MaxRegions || d.Stale || d.Updated <= 0 ||
		now.Sub(time.Unix(d.Updated, 0)) > StaleAfter || time.Unix(d.Updated, 0).Sub(now) > Interval {
		return nil, errors.New("serving-region discovery is empty, stale or invalid")
	}
	cells := make([]string, 0, len(d.Regions))
	for _, region := range d.Regions {
		name, _, _ := strings.Cut(region.ID, "-")
		entry, known := catalog.LookupName(name)
		if !known {
			return nil, fmt.Errorf("serving-region discovery includes unsupported cell %q", region.ID)
		}
		id, err := naming.RegionCell(entry.Cell).Name()
		if err != nil || id != region.ID || slices.Contains(cells, entry.Cell) {
			return nil, fmt.Errorf("serving-region discovery includes duplicate or unsupported cell %q", region.ID)
		}
		cells = append(cells, entry.Cell)
	}
	slices.Sort(cells)
	return cells, nil
}

// entries is ordered: placement assigns permanent members in this order.
var entries = [...]Entry{
	{Cell: GRU, OCIRegion: "sa-saopaulo-1", OCIRegionKey: "GRU", City: "São Paulo", Country: "BR", Latitude: -23.43, Longitude: -46.47},
	{Cell: SFO, OCIRegion: "us-sanjose-1", OCIRegionKey: "SJC", City: "San Jose", Country: "US", Latitude: 37.34, Longitude: -121.89},
	{Cell: FRA, OCIRegion: "eu-frankfurt-1", OCIRegionKey: "FRA", City: "Frankfurt", Country: "DE", Latitude: 50.11, Longitude: 8.68},

// Names returns the ordered lower-case cell tokens used in NATS subjects.
func Names() []string {
	names := make([]string, 0, Len)
	for _, entry := range entries {
		names = append(names, entry.Name())
	}
	return names
}

// LookupName returns the entry whose lower-case token is name.
func LookupName(name string) (Entry, bool) {
	for _, entry := range entries {
		if entry.Name() == name {
			return entry, true
		}
	}
	return Entry{}, false
}

